69: /**
70:  * Class to display a UML note in a diagram
71:  * Since we don't need stereotypes for the note and an
72:  * empty stereotype textfield causes problems with the
73:  * note layout, I subclass FigNode instead of FigNodeModelElement.
74:  */
75: public class FigComment
76:     extends FigNodeModelElement
77:     implements VetoableChangeListener,
78: 	       DelayedVChangeListener,
79: 	       MouseListener,
80: 	       KeyListener,
81: 	       PropertyChangeListener
82: {
83:     protected static Logger cat = Logger.getLogger(FigComment.class);
84: 
85:     ////////////////////////////////////////////////////////////////
86:     // constants
87: 
88:     // public final int MARGIN = 2;
89:     public int px = 0;
90:     public int y = 0;
91:     public int width = 80;
92:     public int height = 60;
93:     public int gapY = 10;
94: 
95:     protected boolean _readyToEdit = true;
96: 
97:     public static Font LABEL_FONT;
98:     public static Font ITALIC_LABEL_FONT;
99:     public final int MARGIN = 2;
100: 
101:     static {
102:         LABEL_FONT = LookAndFeelMgr.getInstance().getSmallFont();
103:         ITALIC_LABEL_FONT = new Font(LABEL_FONT.getFamily(),
104: 				     Font.ITALIC,
105: 				     LABEL_FONT.getSize());
106:     }
107: 
108:     ////////////////////////////////////////////////////////////////
109:     // instance variables
110: 
111:     // The model element the note is attached to.
112:     private Object _noteOwner = null;
113: 
114:     // The figure that holds the text of the note.
115:     FigText _text;
116: 
117:     FigPoly _body;
118:     FigPoly _urCorner;
119: 
120:     ////////////////////////////////////////////////////////////////
121:     // constructors
122: 
123:     public FigComment() {
124:         _body = new FigPoly(Color.black, Color.white);
125:         _body.addPoint(px, y);
126:         _body.addPoint(px + width - 1 - gapY, y);
127:         _body.addPoint(px + width - 1, y + gapY);
128:         _body.addPoint(px + width - 1, y + height - 1);
129:         _body.addPoint(px, y + height - 1);
130:         _body.addPoint(px, y);
131:         _body.setFilled(true);
132:         _body.setLineWidth(1);
133: 
134:         _urCorner = new FigPoly(Color.black, Color.white);
135:         _urCorner.addPoint(px + width - 1 - gapY, y);
136:         _urCorner.addPoint(px + width - 1, y + gapY);
137:         _urCorner.addPoint(px + width - 1 - gapY, y + gapY);
138:         _urCorner.addPoint(px + width - 1 - gapY, y);
139:         _urCorner.setFilled(true);
140:         _urCorner.setLineWidth(1);
141: 
142:         setBigPort(new FigRect(px, y, width, height, null, null));
143:         getBigPort().setFilled(false);
144:         getBigPort().setLineWidth(0);
145: 
146:         _text = new FigText(2, 2, width - 2 - gapY, height - 4, true);
147:         _text.setFont(LABEL_FONT);
148:         _text.setTextColor(Color.black);
149:         _text.setMultiLine(true);
150:         _text.setAllowsTab(false);
151:         // _text.setText(placeString());
152:         _text.setJustification(FigText.JUSTIFY_LEFT);
153:         _text.setFilled(false);
154:         _text.setLineWidth(0);
155:         //_text.setLineColor(Color.white);
156: 
157:         // add Figs to the FigNode in back-to-front order
158:         addFig(getBigPort());
159:         addFig(_body);
160:         addFig(_urCorner);
161:         addFig(_text);
162: 
163:         setBlinkPorts(false); //make port invisble unless mouse enters
164:         Rectangle r = getBounds();
165:         setBounds(r.x, r.y, r.width, r.height);
166:         updateEdges();
167: 
168:         _readyToEdit = false;
169:     }
170: 
171:     /**
172:      * Construct a new note
173:      *
174:      * @param gm The graphmodel
175:      * @param node The underlying MComment node
176:      */
177:     public FigComment(GraphModel gm, Object node) {
178:         this();
179:         setOwner(node);
180:     }
181: 
182:     /**
183:      * Create a note for a given model element.
184:      * @deprecated as of 0.17.1 nobody should use this constructor since it not only constructs
185:      * the fig but also the model behind it. That should not be done by a fig which is only a view to the model
186:      * @param element The annotated model element.
187:      */
188:     public FigComment(Object element) {
189:         this(); // Construct the figure.
190: 
191:         if(!ModelFacade.isAModelElement(element)){
192:             throw new IllegalArgumentException();
193:         }
194: 
195: 	// Create a new Comment node.
196:         Object comment =
197: 	    UmlFactory.getFactory().getCore().createComment();
198:         setOwner(comment); // Set it as the owner of the figure.
199: 	// Tell the annotated element, that it has a comment now.
200:         ModelFacade.addComment(element, comment);
201: 
202:         // Notes in statechart diagrams need a special treatment, cause
203:         // the nodes in them don't necessary have a namespace, where
204:         // we could add the note. So I added this hack... :-(
205:         // Andreas Rueckert <a_rueckert@gmx.net>
206:         if (ModelFacade.isAStateVertex(element)) {
207: 
208: 	    // If the current target is a statechart diagram, we have to
209: 	    // check, if we are editing the diagram.
210:             ProjectBrowser pb = ProjectBrowser.getInstance(); 
211:             if (TargetManager.getInstance().getTarget() instanceof UMLStateDiagram) { 
212:                 StateDiagramGraphModel gm =
213: 		    (StateDiagramGraphModel)
214: 		    (((UMLStateDiagram) TargetManager.getInstance().getTarget()).getGraphModel());
215: 		// We are editing, so we set the Namespace directly.
216:                 ModelFacade.setNamespace(comment, gm.getNamespace());
217:             }
218:         } else {
219: 	    // Add the comment to the same namespace as the annotated element.
220:             ModelFacade.setNamespace(comment, ModelFacade.getNamespace(element));
221:         }
222: 
223:         storeNote(placeString()); // Set the default text for this figure type.
224:     }
225: 
226:     /**
227:      * Get the default text for this figure.
228:      *
229:      * @return The default text for this figure.
230:      */
231:     public String placeString() {
232:         String placeString = retrieveNote();
233:         if (placeString == null)
234:             placeString = "new note";
235:         return placeString;
236:     }
237: 
238:     /**
239:      * Clone this figure.
240:      *
241:      * @return The cloned figure.
242:      */
243:     public Object clone() {
244:         FigComment figClone = (FigComment) super.clone();
245:         Iterator it = figClone.getFigs(null).iterator();
246:         figClone.setBigPort((FigRect) it.next());
247:         figClone._body = (FigPoly) it.next();
248:         figClone._urCorner = (FigPoly) it.next();
249:         figClone._text = (FigText) it.next();
250:         return figClone;
251:     }
252: 
253:     ////////////////////////////////////////////////////////////////
254:     // event handlers
255: 
256:     /**
257:      * See FigNodeModelElement.java for more info on these methods.
258:      */
259: 
260:     /** If the user double clicks on any part of this FigNode, pass it
261:      *  down to one of the internal Figs.  This allows the user to
262:      *  initiate direct text editing. */
