454:     public void setBounds(int x, int y, int w, int h) {
455:         if (_text == null)
456:             return;
457: 
458:         Rectangle oldBounds = getBounds();
459: 
460:         // Resize the text figure
461:         _text.setBounds(x + 2, y + 2, w - 4 - gapY, h - 4);
462: 
463:         // Resize the big port around the figure
464:         getBigPort().setBounds(x, y, w, h);
465: 
466:         // Since this is a complex polygon, there's no easy way to resize it.
467:         Polygon newPoly = new Polygon();
468:         newPoly.addPoint(x, y);
469:         newPoly.addPoint(x + w - 1 - gapY, y);
470:         newPoly.addPoint(x + w - 1, y + gapY);
471:         newPoly.addPoint(x + w - 1, y + h - 1);
472:         newPoly.addPoint(x, y + h - 1);
473:         newPoly.addPoint(x, y);
474:         _body.setPolygon(newPoly);
475: 
476:         // Just move the corner to it's new position.
477:         _urCorner.setBounds(x + w - 1 - gapY, y, gapY, gapY);
478: 
479:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
480:         firePropChange("bounds", oldBounds, getBounds());
481:     }
