182:     /**
183:      * Create a note for a given model element.
184:      * @deprecated as of 0.17.1 nobody should use this constructor since it not only constructs
185:      * the fig but also the model behind it. That should not be done by a fig which is only a view to the model
186:      * @param element The annotated model element.
187:      */
188:     public FigComment(Object element) {
189:         this(); // Construct the figure.
190: 
191:         if(!ModelFacade.isAModelElement(element)){
192:             throw new IllegalArgumentException();
193:         }
194: 
195: 	// Create a new Comment node.
196:         Object comment =
197: 	    UmlFactory.getFactory().getCore().createComment();
198:         setOwner(comment); // Set it as the owner of the figure.
199: 	// Tell the annotated element, that it has a comment now.
200:         ModelFacade.addComment(element, comment);
201: 
202:         // Notes in statechart diagrams need a special treatment, cause
203:         // the nodes in them don't necessary have a namespace, where
204:         // we could add the note. So I added this hack... :-(
205:         // Andreas Rueckert <a_rueckert@gmx.net>
206:         if (ModelFacade.isAStateVertex(element)) {
207: 
208: 	    // If the current target is a statechart diagram, we have to
209: 	    // check, if we are editing the diagram.
210:             ProjectBrowser pb = ProjectBrowser.getInstance(); 
211:             if (TargetManager.getInstance().getTarget() instanceof UMLStateDiagram) { 
212:                 StateDiagramGraphModel gm =
213: 		    (StateDiagramGraphModel)
214: 		    (((UMLStateDiagram) TargetManager.getInstance().getTarget()).getGraphModel());
215: 		// We are editing, so we set the Namespace directly.
216:                 ModelFacade.setNamespace(comment, gm.getNamespace());
217:             }
218:         } else {
219: 	    // Add the comment to the same namespace as the annotated element.
220:             ModelFacade.setNamespace(comment, ModelFacade.getNamespace(element));
221:         }
222: 
223:         storeNote(placeString()); // Set the default text for this figure type.
224:     }
