398:     ////////////////////////////////////////////////////////////////
399:     // user interaction methods
400: 
401:     protected void textEdited(FigText ft) throws PropertyVetoException {
402:         if (ft == _text)
403:             storeNote(ft.getText());
404:     }
405: 
406:     public void setEnclosingFig(Fig encloser) {
407:         super.setEnclosingFig(encloser);
408:     }
409: 
410:     ////////////////////////////////////////////////////////////////
411:     // accessor methods
412: 
413:     /**
414:      * Store a note in the associated model element.
415:      *
416:      * @param note The note to store.
417:      */
418:     public final void storeNote(String note) {
419:         if (getOwner() != null)
420:              ModelFacade.setName(getOwner(), note);
421:     }
422: 
423:     /**
424:      * Retrieve the note from the associated model element.
425:      *
426:      * @return The note from the associated model element.
427:      */
428:     public final String retrieveNote() {
429:         return (getOwner() != null)
430: 	    ? org.argouml.model.ModelFacade.getName(getOwner())
431: 	    : null;
432:     }
433: 
434:     public boolean getUseTrapRect() {
435:         return true;
436:     }
437: 
438:     /**
439:      * Get the minimum size for the note figure.
440:      *
441:      * @return The minimum size for the note figure.
442:      */
443:     public Dimension getMinimumSize() {
444: 
445:         // Get the size of the text field.
446:         Dimension textMinimumSize = _text.getMinimumSize();
447: 
448:         // And add the gaps around the textfield to get the minimum
449:         // size of the note.
450:         return new Dimension(textMinimumSize.width + 4 + gapY,
451: 			     textMinimumSize.height + 4);
452:     }
453: 
454:     public void setBounds(int x, int y, int w, int h) {
455:         if (_text == null)
456:             return;
457: 
458:         Rectangle oldBounds = getBounds();
459: 
460:         // Resize the text figure
461:         _text.setBounds(x + 2, y + 2, w - 4 - gapY, h - 4);
462: 
463:         // Resize the big port around the figure
464:         getBigPort().setBounds(x, y, w, h);
465: 
466:         // Since this is a complex polygon, there's no easy way to resize it.
467:         Polygon newPoly = new Polygon();
468:         newPoly.addPoint(x, y);
469:         newPoly.addPoint(x + w - 1 - gapY, y);
470:         newPoly.addPoint(x + w - 1, y + gapY);
471:         newPoly.addPoint(x + w - 1, y + h - 1);
472:         newPoly.addPoint(x, y + h - 1);
473:         newPoly.addPoint(x, y);
474:         _body.setPolygon(newPoly);
475: 
476:         // Just move the corner to it's new position.
477:         _urCorner.setBounds(x + w - 1 - gapY, y, gapY, gapY);
478: 
479:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
480:         firePropChange("bounds", oldBounds, getBounds());
481:     }
482: 
483:     protected void updateBounds() {
484:         Rectangle bbox = getBounds();
485:         Dimension minSize = getMinimumSize();
486:         bbox.width = Math.max(bbox.width, minSize.width);
487:         bbox.height = Math.max(bbox.height, minSize.height);
488:         setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
489:     }
490: 
491:     ///////////////////////////////////////////////////////////////////
492:     // Internal methods
493: 
494:     /**
495:      * This is called aftern any part of the UML MModelElement has
496:      * changed. This method automatically updates the note FigText.
497:      */
498:     protected final void modelChanged(MElementEvent mee) {
499:         super.modelChanged(mee);
500: 
501:         String noteStr = retrieveNote();
502:         if (noteStr != null)
503:             _text.setText(noteStr);
504: 
505:     }
506: 
507:     /**
508:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateNameText()
509:      */
510:     protected void updateNameText() {
511:         if (getOwner() != null) {
512:             String text = org.argouml.model.ModelFacade.getName(getOwner());
513:             if (text != null) {
514:                 _text.setText(text);
515:                 calcBounds();
516:                 setBounds(getBounds());
517:             }
518:         }
519:     }
520: 
521: } /* end class FigComment */

