684:     private void checkType(MOperation op, String text, String type)
685: 	throws ParseException
686:     {
687: 	ParserDisplay.SINGLETON.parseOperation(text, op);
688: 	Collection ret =
689: 	    UmlHelper.getHelper().getCore().getReturnParameters(op);
690: 	Iterator it = ret.iterator();
691: 	assertTrue(
692: 		   text + " gave extra return value",
693: 		   !(type == null && it.hasNext()));
694: 	assertTrue(
695: 		   text + " lacks return value",
696: 		   !(type != null && !it.hasNext()));
697: 	if (it.hasNext()) {
698: 	    MParameter p = (MParameter) it.next();
699: 	    assertTrue(
700: 		       text + " gave wrong return",
701: 		       (type == null && p.getType() == null)
702: 		       || (type != null && type.equals(p.getType().getName())));
703: 	}
704: 	assertTrue(text + " gave extra return value", !it.hasNext());
705:     }
