707:     private void checkParameters(MOperation op, String text, String params[])
708: 	throws ParseException
709:     {
710: 	int i;
711: 
712: 	ParserDisplay.SINGLETON.parseOperation(text, op);
713: 	Collection prm = op.getParameters();
714: 	Iterator it = prm.iterator();
715: 	assertTrue(
716: 		   text + " lacks parameters",
717: 		   !(params.length > 0 && !it.hasNext()));
718: 	for (i = 0; i + 3 < params.length; i += 4) {
719: 	    MParameter p;
720: 	    do {
721: 		assertTrue(text + " lacks parameters", it.hasNext());
722: 		p = (MParameter) it.next();
723: 	    } while (p.getKind().equals(MParameterDirectionKind.RETURN));
724: 	    assertTrue(
725: 		       text + "gave wrong inout in parameter " + (i / 4),
726: 		       params[i].equals(p.getKind().getName()));
727: 	    assertTrue(
728: 		       text + "gave wrong name in parameter " + (i / 4),
729: 		       params[i + 1].equals(p.getName()));
730: 	    assertTrue(
731: 		       text + "gave wrong type in parameter " + (i / 4),
732: 		       params[i + 2].equals(p.getType().getName()));
733: 	    assertTrue(text + "gave wrong default value in parameter " 
734: 		       + (i / 4),
735: 		       (params[i + 3] == null && p.getDefaultValue() == null)
736: 		       || (params[i + 3] != null && p.getDefaultValue() != null)
737: 		       && params[i + 3].equals(p.getDefaultValue().getBody()));
738: 	}
739: 	while (it.hasNext()) {
740: 	    MParameter p = (MParameter) it.next();
741: 	    assertTrue(
742: 		       text + " gave extra parameters",
743: 		       p.getKind().equals(MParameterDirectionKind.RETURN));
744: 	}
745:     }
