924:     private void checkBases(MClassifierRole cr, String text, String bases[])
925: 	throws ParseException
926:     {
927: 	int i;
928: 	Collection c;
929: 	Iterator it;
930: 	MClassifier cls;
931: 
932: 	ParserDisplay.SINGLETON.parseClassifierRole(cr, text);
933: 	c = cr.getBases();
934: 	it = c.iterator();
935:     checkAllValid : 
936: 	while (it.hasNext()) {
937: 	    cls = (MClassifier) it.next();
938: 	    for (i = 0; i < bases.length; i++)
939: 		if (bases[i].equals(cls.getName()))
940: 		    continue checkAllValid;
941: 	    assertTrue(
942: 		       "Base "
943: 		       + cls.getName()
944: 		       + " falsely "
945: 		       + "generated by "
946: 		       + text,
947: 		       false);
948: 	}
949: 
950:     checkAllExist : 
951: 	for (i = 0; i < bases.length; i++) {
952: 	    it = c.iterator();
953: 	    while (it.hasNext()) {
954: 		cls = (MClassifier) it.next();
955: 		if (bases[i].equals(cls.getName()))
956: 		    continue checkAllExist;
957: 	    }
958: 	    assertTrue("Base " + bases[i] + " was not generated by " + text,
959: 		       false);
960: 	}
961:     }
962: }
